    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    desperate_count = 0
    rich_aggressive = 0

    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                desperate_count += 1
            if opp.get('budget', 0) > 500:
                rich_aggressive += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev.get('bid', 0))

    if budget <= 0:
        return 0.0

    if not alive:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    tight_supply = supply <= 17
    loose_supply = supply >= 22

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 2

    if day >= 8:
        urgency += 1

    pressure = 0
    if tight_supply:
        pressure += 2
    elif not loose_supply:
        pressure += 1

    if highest_prev >= 110:
        pressure += 3
    elif highest_prev >= 85:
        pressure += 2
    elif highest_prev >= 55:
        pressure += 1

    pressure += min(desperate_count, 2)

    if urgency >= 5:
        bid = max(78.0, highest_prev + 3.0)
    elif urgency >= 3:
        if highest_prev >= 100:
            bid = 72.0 if loose_supply else 88.0
        elif highest_prev >= 70:
            bid = highest_prev + 2.5
        else:
            bid = 58.0 if not tight_supply else 76.0
    else:
        if loose_supply:
            bid = 16.0
        elif tight_supply:
            if highest_prev >= 100:
                bid = 28.0
            elif highest_prev >= 70:
                bid = 46.0
            else:
                bid = 34.0
        else:
            if avg_prev >= 90:
                bid = 22.0
            elif avg_prev >= 60:
                bid = 36.0
            else:
                bid = 30.0

    if rich_aggressive >= 2 and urgency <= 2:
        bid *= 0.85

    reserve = 0.0
    if hp <= 4 or no_water_days >= 1:
        reserve = 0.0
    elif day <= 5:
        reserve = 140.0
    else:
        reserve = 70.0

    max_affordable = max(0.0, budget - reserve)
    if urgency >= 5:
        max_affordable = budget

    bid = min(bid, max_affordable)

    if urgency >= 4 and bid < 65.0 and budget >= 65.0:
        bid = 65.0

    if bid < 0:
        bid = 0.0

    return float(min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    hp = int(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opponents.append((opp_id, opp))

    # If alone, bid low but enough to survive.
    if not alive_opponents:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Read yesterday bids from each opponent's previous_trace.
    yesterday_bids = []
    for _, opp in alive_opponents:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    # Estimate a competitive bid target from yesterday.
    if yesterday_bids:
        # Use upper quantile to react to aggressive bidders without overpaying.
        sorted_bids = sorted(yesterday_bids)
        idx = int(len(sorted_bids) * 0.75)
        if idx < 0:
            idx = 0
        if idx >= len(sorted_bids):
            idx = len(sorted_bids) - 1
        q75 = float(sorted_bids[idx])

        # Clearing-level proxy: slightly above q75 but not too high.
        # If q75 is already extremely high, cap to avoid mirroring Alex-like overbidding.
        target = q75 * 0.98 + 1.0
        if q75 >= DAILY_SALARY * 0.95:
            target = min(target, DAILY_SALARY * 0.75)
    else:
        target = DAILY_SALARY * 0.55

    # Supply adjustment: in higher supply, we can bid lower.
    # Map supply in [MIN_SUPPLY, MAX_SUPPLY] to multiplier in [1.05, 0.9]
    if MAX_SUPPLY > MIN_SUPPLY:
        t = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    else:
        t = 0.5
    if t < 0.0:
        t = 0.0
    if t > 1.0:
        t = 1.0
    supply_mult = 1.05 - 0.15 * t

    # Urgency based on hp/no_water_days.
    urgency_mult = 1.0
    if hp <= 2:
        urgency_mult = 1.25
    elif hp <= 4:
        urgency_mult = 1.12

    if no_water_days >= 2:
        urgency_mult *= 1.10

    # Final bid computation.
    bid = target * supply_mult * urgency_mult

    # Bound by budget and keep within reasonable fraction of salary.
    # If my budget is low, go all-in only when hp is critical.
    if budget <= 0.0:
        return 0.0

    max_reasonable = DAILY_SALARY * 0.75
    if hp <= 2:
        max_reasonable = DAILY_SALARY * 0.95

    bid = min(bid, max_reasonable)
    bid = min(bid, budget)

    # Ensure non-negative
    if bid < 0.0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = {aid: o for aid, o in opponents_status.items() if o['alive']}
    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.3)

    # Collect previous bids from alive opponents
    previous_bids = []
    for opp in alive_opponents.values():
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            previous_bids.append(prev['bid'])

    # Determine base bid
    if previous_bids:
        highest_prev = max(previous_bids)
    else:
        highest_prev = 0

    # Adjust based on our HP
    if hp <= 2:
        # Desperate, bid high but within budget
        target = min(budget, DAILY_SALARY * 0.9)
    elif hp <= 5:
        # Moderate need, slightly above previous highest if not too large
        target = min(budget, max(DAILY_SALARY * 0.6, highest_prev + 1.0))
    else:
        # Healthy, bid low to conserve
        target = min(budget, DAILY_SALARY * 0.4)

    # Ensure we have enough for future if budget is low
    if budget < DAILY_SALARY * 0.5 and hp > 3:
        target = min(target, budget * 0.3)

    # Keep bid positive and not exceed budget
    return max(1.0, min(budget, target))
